&query_place_id=ChIJvZM0qjgvdTER3P1JxXG_juM"},{"ward":"Sài Gòn","name":"Đông A Books - Showroom Đường sách","street":"Gian M14, đường Nguyễn Văn Bình","category":"nha_sach","phone":"02835210690","key":"donga:nguyen-van-binh:m14","source":"https://www.google.com/maps/search/?api=1&query=Dong+A+Bookstore+Nguyen+Van+Binh&query_place_id=ChIJQ3BWZo0vdTER6z3VTXH-hJ0","old":"Gian M14 đường Nguyễn Văn Bình, phường Bến Nghé cũ, Quận 1","place":"ChIJQ3BWZo0vdTER6z3VTXH-hJ0","evidence":"Google Maps định danh showroom sách Đông A riêng tại gian M14 đường sách, số điện thoại trên hồ sơ; cần đối chiếu chủ gian khi ghé.","ward_new":"Sài Gòn","address_line":"Gian M14, đường Nguyễn Văn Bình, phường Sài Gòn, TP. Hồ Chí Minh","address_legacy":"Gian M14 đường Nguyễn Văn Bình, phường Bến Nghé cũ, Quận 1, TP.HCM cũ","google_place_id":"ChIJQ3BWZo0vdTER6z3VTXH-hJ0","google_maps_url":"https://www.google.com/maps/search/?api=1&query=%C4%90%C3%B4ng%20A%20Books%20-%20Showroom%20%C4%90%C6%B0%E1%BB%9Dng%20s%C3%A1ch%20Gian%20M14%2C%20%C4%91%C6%B0%E1%BB%9Dng%20Nguy%E1%BB%85n%20V%C4%83n%20B%C3%ACnh%20TP%20HCM&query_place_id=ChIJQ3BWZo0vdTER6z3VTXH-hJ0"}]'::jsonb) x(
  ward text,ward_new text,name text,street text,category text,phone text,
  key text,source text,old text,place text,evidence text,
  address_line text,address_legacy text,google_place_id text,google_maps_url text
 )
), vetted AS (
 SELECT * FROM src s
 WHERE ward_new IN ('Sài Gòn','Tân Định','Bến Thành')
  AND category IN ('nha_sach','van_phong_pham') AND source LIKE 'https://%'
  AND google_place_id LIKE 'ChIJ%' AND google_maps_url LIKE 'https://www.google.com/maps/%'
  AND NOT EXISTS(
   SELECT 1 FROM public.customers c WHERE c.province='TP Hồ Chí Minh'
    AND (lower(trim(c.name))=lower(trim(s.name))
     OR lower(trim(c.address_line))=lower(trim(s.address_line))
     OR (s.phone IS NOT NULL AND regexp_replace(coalesce(c.phone,''),'[^0-9]','','g')=s.phone))
  )
  AND NOT EXISTS(
   SELECT 1 FROM public.field_prospects p WHERE
   p.research_source_key=s.key OR p.google_place_id=s.google_place_id
    OR (p.province='TP Hồ Chí Minh' AND (
      lower(trim(p.address_line))=lower(trim(s.address_line))
      OR (lower(trim(p.name))=lower(trim(s.name)) AND p.district='Quận 1')
      OR (s.phone IS NOT NULL AND regexp_replace(coalesce(p.phone,''),'[^0-9]','','g')=s.phone)))
  )
), imported AS (
 INSERT INTO public.field_prospects (
  id,area_visit_id,owner_sub,name,address_line,province,district,ward_new,
  address_legacy,category,phone,tax_code,note,status,source_kind,
  research_source_key,research_source_url,research_batch,google_maps_url,google_place_id)
 SELECT gen_random_uuid(),NULL,'ef943de4-18f7-49ef-8340-eefb18855534',
  s.name,s.address_line,'TP Hồ Chí Minh','Quận 1',s.ward_new,s.address_legacy,
  s.category,s.phone,NULL,
  'Nguồn công khai 22/11/2026; CHƯA GHÉ; không có GPS thực địa. '||s.evidence||' Nguồn: '||s.source,
  'new','manual',s.key,s.source,
  '2026-11-22-hcm-old-sg-tandinh-benthanh-165',
  s.google_maps_url,s.google_place_id
 FROM vetted s
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING ward_new,name,phone,google_place_id
)
SELECT ward_new,name,phone,google_place_id FROM imported ORDER BY ward_new,name;

-- Match already imported stores to independently observed place identifiers.
-- Never modify legacy district/province, coordinates or historical visit records.
WITH src AS (SELECT x.key,x.place FROM jsonb_to_recordset('[{"key":"pnc:nguyen-hue:12bis","place":"ChIJ4d3K7IwvdTERo-RTCofPrMM"},{"key":"pnc:saigon-centre:65-le-loi","place":"ChIJQY9kQ0cvdTERJj4LJH30YmU"},{"key":"pnc:book-city-nguyen-trai:212","place":"ChIJXUZJ-movdTERfLsuZ0Py72A"},{"key":"nxbkimdong:248-cong-quynh","place":"ChIJHy22GhgvdTERE8Nbcb9T8fM"},{"key":"teayoushop:214-19-8c-nguyen-van-nguyen","place":"ChIJpxKoq88pdTERpBZj4SRqgYs"}]'::jsonb) x(key text,place text))
UPDATE public.field_prospects p
SET google_place_id=s.place,
    google_maps_url='https://www.google.com/maps/search/?api=1&query='||replace(p.name,' ','+')||'&query_place_id='||s.place
FROM src s
WHERE p.research_source_key=s.key
 AND p.province='TP Hồ Chí Minh' AND p.ward_new IN ('Sài Gòn','Tân Định','Bến Thành')
 AND (p.google_place_id IS NULL OR p.google_place_id=s.place)
 AND (p.google_place_id IS DISTINCT FROM s.place OR p.google_maps_url IS NULL)
 AND NOT EXISTS (SELECT 1 FROM public.field_prospects existing
   WHERE existing.google_place_id=s.place AND existing.id<>p.id);
